CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS projects(id SERIAL PRIMARY KEY,name TEXT NOT NULL,repository TEXT NOT NULL,description TEXT NOT NULL,stack JSONB NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'healthy',health_score INT NOT NULL DEFAULT 96,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS project_files(id SERIAL PRIMARY KEY,project_id INT REFERENCES projects(id) ON DELETE CASCADE,path TEXT NOT NULL,language TEXT NOT NULL,size_bytes INT NOT NULL DEFAULT 0,risk TEXT NOT NULL DEFAULT 'low',summary TEXT NOT NULL DEFAULT '',updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS project_events(id SERIAL PRIMARY KEY,project_id INT REFERENCES projects(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,actor TEXT NOT NULL DEFAULT 'system',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS health_checks(id SERIAL PRIMARY KEY,project_id INT REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,status TEXT NOT NULL,score INT NOT NULL,detail TEXT NOT NULL,checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS conversations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id INT REFERENCES projects(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id UUID REFERENCES conversations(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_events_project_time ON project_events(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_messages_conversation_time ON messages(conversation_id,created_at);
INSERT INTO projects(id,name,repository,description,stack,status,health_score) VALUES(1,'VoicePilot','aithavignesh/voicepilot-as03','Voice-first AI engineering copilot that lets developers talk to a project instead of navigating dashboards.','["TypeScript","Node.js","Express","PostgreSQL","OpenAI","Web Speech API"]','healthy',96) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,repository=EXCLUDED.repository,description=EXCLUDED.description,stack=EXCLUDED.stack,status=EXCLUDED.status,health_score=EXCLUDED.health_score,updated_at=NOW();
INSERT INTO project_files(project_id,path,language,size_bytes,risk,summary) SELECT 1,* FROM (VALUES ('src/server.ts','TypeScript',8200,'low','Express API, AI orchestration and project routes.'),('public/index.html','HTML',10400,'low','Voice-first dashboard and command console.'),('public/app.js','JavaScript',12400,'low','Speech recognition, chat and live project insights.'),('schema.sql','SQL',5100,'medium','PostgreSQL schema for project intelligence and conversations.'),('README.md','Markdown',7200,'low','Architecture, setup and hackathon demo guide.')) v(path,language,size_bytes,risk,summary) WHERE NOT EXISTS (SELECT 1 FROM project_files WHERE project_id=1 AND project_files.path=v.path);
INSERT INTO health_checks(project_id,name,status,score,detail) SELECT 1,* FROM (VALUES ('TypeScript','passing',100,'Strict type checking enabled.'),('API','passing',98,'Core project and conversation endpoints are available.'),('Database','passing',97,'PostgreSQL schema and indexes are ready.'),('Dependencies','warning',88,'Review dependency freshness before production hardening.'),('Security','passing',95,'Helmet, validation and bounded inputs are enabled.')) v(name,status,score,detail) WHERE NOT EXISTS (SELECT 1 FROM health_checks WHERE project_id=1 AND name=v.name);
INSERT INTO project_events(project_id,type,title,description,actor) SELECT 1,* FROM (VALUES ('deploy','VoicePilot foundation deployed','Full-stack voice copilot foundation is ready for end-to-end testing.','system'),('test','Database schema verified','Project, health, event and conversation tables are available.','system'),('commit','Voice command workflow added','Voice input now reaches the project intelligence API.','aitha'),('scan','Health baseline created','Baseline health checks collected for the demo project.','system'),('feature','Intent and entity extraction','Commands are classified into project snapshot, health, activity and recommendation intents.','AI')) v(type,title,description,actor) WHERE NOT EXISTS (SELECT 1 FROM project_events WHERE project_id=1 AND title=v.title);